import { GoogleGenAI, Schema } from "@google/genai";
import { GeneratedQuestionBatch } from "../types";

// Using gemini-2.0-flash as it is more likely to be enabled for the provided API key than the preview 3 model
const MODEL_NAME = 'gemini-2.0-flash'; 

const getSystemPrompt = (categories: string[], isHots: boolean) => {
  const count = 3; // Fixed as per requirement

  let categoryInstruction = "";
  if (categories.length >= 3) {
    // If all categories (or at least 3) are selected, enforce 1 of each for the 3 questions.
    categoryInstruction = `\n\nDISTRIBUSI WAJIB: Karena total 3 soal, kamu WAJIB membuat komposisi eksak: 1 soal TWK, 1 soal TIU, dan 1 soal TKP.`;
  } else if (categories.length > 0) {
    categoryInstruction = `\n\nDISTRIBUSI: Buat soal HANYA untuk kategori: ${categories.join(', ')}. Distribusikan 3 soal tersebut secara merata.`;
  } else {
    categoryInstruction = `\n\nDISTRIBUSI WAJIB: 1 soal TWK, 1 soal TIU, 1 soal TKP.`;
  }

  const hotsInstruction = isHots 
    ? `\n\nLEVEL: HOTS (High Order Thinking Skills) - TINGKAT SULIT.
    - Soal harus berbasis analisis kasus (case-based) dan penalaran mendalam, BUKAN hafalan.
    - Opsi jawaban harus sangat homogen (mirip) dan mengecoh (distractor kuat).
    - TWK: Fokus pada implementasi/pengamalan nilai dalam kasus nyata yang kompleks.
    - TIU: Logika verbal atau numerik cerita yang membutuhkan pemecahan masalah bertingkat.
    - TKP: Situasi dilematis di mana semua pilihan tampak benar (grey area), menuntut kematangan sikap profesional.`
    : `\n\nLEVEL: Standar CAT CPNS. Kesulitan moderat sesuai kisi-kisi BKN.`;

  return `# SYSTEM PROMPT — CPNS SKD QUESTION GENERATOR (CAT BKN SIMULATOR)

## PERAN
Anda adalah **Penyusun Soal Ahli BKN** yang bertugas membuat soal Seleksi Kompetensi Dasar (SKD) CPNS. Anda menguasai kisi-kisi PERMENPAN-RB terbaru.

## TUGAS
Buat **${count} soal latihan** dalam format JSON berdasarkan **TEKS/TOPIK BERITA** yang diberikan sebagai stimulus.

---

## KISI-KISI & KARAKTERISTIK SOAL (WAJIB PATUH)

### 1. TWK (Tes Wawasan Kebangsaan)
- **Topik**: Nasionalisme, Integritas, Bela Negara, Pilar Negara (Pancasila, UUD 45, NKRI, Bhinneka Tunggal Ika).
- **Gaya**: **Full Penalaran**. Jangan tanya "Siapa", "Kapan", "Dimana". Tanya "Bagaimana sikap...", "Kaitan peristiwa ini dengan sila ke-X...", "Dampak jangka panjang...".
- **Stimulus**: Gunakan berita sebagai konteks untuk menguji pemahaman ideologi.

### 2. TIU (Tes Intelegensia Umum)
- **Topik**: Kemampuan Verbal (Analogi, Silogisme, Analitis) atau Kemampuan Numerik (Soal Cerita).
- **Gaya**: Gunakan data/fakta dari berita untuk membuat soal logika.
- **Contoh**: "Berdasarkan data di atas, jika pertumbuhan X adalah..." atau silogisme dari premis berita.

### 3. TKP (Tes Karakteristik Pribadi)
- **Topik**: Pelayanan Publik, Jejaring Kerja, Sosial Budaya, TIK, Profesionalisme, Anti Radikalisme.
- **Gaya**: Tempatkan peserta sebagai ASN/Pegawai dalam situasi kerja yang relevan dengan berita tersebut.
- **Scoring**: Opsi jawaban berjenjang nilai 1-5. Opsi terbaik (5) harus menunjukkan tindakan paling efektif, proaktif, dan solutif tanpa melanggar aturan.

---

## ATURAN KUALITAS & TRICK QUESTION
1. **Pengecoh (Distractor)**: Untuk TWK/TIU, opsi salah harus sangat masuk akal dan mirip dengan kunci jawaban. Gunakan logika umum yang sering salah kaprah.
2. **Struktur**: Setiap soal harus memiliki **Narasi Stimulus** (2-3 kalimat) dari berita input.
3. **Bahasa**: Baku, formal, ejaan PUEBI.

${hotsInstruction}

---

## FORMAT OUTPUT JSON (STRICT)
Hanya return JSON valid tanpa markdown formatting berlebih di luar blok kode.

\`\`\`json
{
  "questions": [
    {
      "meta": {
        "news_topic": "Ringkasan Topik",
        "question_type": "HOTS/Standard"
      },
      "content": {
        "category": "TWK", 
        "topic": "Nasionalisme",
        "subtopic": "Pengamalan Pancasila",
        "question_text": "Narasi stimulus (berita)... \n\nPertanyaan inti...",
        "options": { "A": "...", "B": "...", "C": "...", "D": "...", "E": "..." },
        "answer_key": {
          "correct_option": "A", // WAJIB ada untuk TWK/TIU. NULL untuk TKP.
          "tkp_points": null // WAJIB NULL untuk TWK/TIU. Isi object { "A": 1, "B": 2, ... "E": 5 } untuk TKP.
        },
        "explanation": "Pembahasan lengkap..."
      }
    }
  ]
}
\`\`\`
${categoryInstruction}
`;
};

const getPdfSystemPrompt = () => {
  return `# SYSTEM PROMPT - PDF QUESTION PARSER & EXTRACTOR

## PERAN
Anda adalah mesin OCR dan Parser cerdas yang bertugas mengonversi dokumen PDF menjadi format soal standar CAT BKN (JSON).

## PRIORITAS UTAMA: EKSTRAKSI
Dokumen ini kemungkinan besar berisi **BANK SOAL** atau **LATIHAN SOAL** yang sudah ada (Soal + Pilihan Ganda).
Tugas utama Anda adalah **MENGEKSTRAK** soal-soal tersebut ke dalam format JSON.

### ATURAN EKSTRAKSI (JIKA DITEMUKAN SOAL)
1. **KUANTITAS**: Ekstrak **SEBANYAK MUNGKIN** soal yang bisa Anda temukan dalam dokumen. Jangan batasi jumlahnya, gunakan kapasitas output maksimal untuk memuat semua soal yang terdeteksi.
2. **AKURASI TEKS**: Salin teks soal (question_text) dan pilihan (options) persis seperti di dokumen. Jangan mengubah makna.
3. **KUNCI JAWABAN**:
   - Jika ada kunci jawaban tertulis di dokumen, GUNAKAN ITU.
   - Jika tidak ada kunci, ANDA WAJIB MENYELESAIKANNYA dan menentukan kunci yang benar ('correct_option').
4. **KATEGORI**: Klasifikasikan setiap soal secara otomatis ke dalam **TWK** (Wawasan Kebangsaan), **TIU** (Intelegensia Umum), atau **TKP** (Karakteristik Pribadi) berdasarkan kontennya.
5. **PEMBAHASAN**: Jika dokumen memuat pembahasan, salin. Jika tidak, buat pembahasan singkat ('explanation') yang logis.
6. **STIMULUS/BACAAN**: Jika soal memiliki bacaan panjang atau data tabel sebelumnya, masukkan itu ke dalam field 'question_text' agar soal mandiri (self-contained).

### SKEMA OUTPUT JSON
\`\`\`json
{
  "questions": [
    {
      "meta": {
        "news_topic": "Judul Dokumen/Asal PDF",
        "question_type": "PDF Extraction"
      },
      "content": {
        "category": "TWK", // atau TIU / TKP
        "topic": "Topik yang relevan",
        "subtopic": "Subtopik",
        "question_text": "Teks soal lengkap...",
        "options": { "A": "...", "B": "...", "C": "...", "D": "...", "E": "..." },
        "answer_key": {
          "correct_option": "A", // Kunci jawaban
          "tkp_points": null // Isi jika TKP (5,4,3,2,1), null jika TWK/TIU
        },
        "explanation": "Pembahasan..."
      }
    }
  ]
}
\`\`\`

### CATATAN PENTING
- Jika dokumen BUKAN soal (hanya materi/teks biasa), barulah Anda generate soal latihan dari materi tersebut (Mode Generasi).
- Namun jika terlihat seperti soal (ada nomor 1, 2, 3... opsi A, B, C...), **MODE EKSTRAKSI ADALAH PRIORITAS MUTLAK**.
`;
};

const getAiInstance = () => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

export const generateQuestionBatch = async (newsText: string, categories: string[] = [], isHots: boolean = false): Promise<GeneratedQuestionBatch> => {
  const ai = getAiInstance();

  // Count is implicitly 3 based on system prompt logic
  const systemPrompt = getSystemPrompt(categories, isHots);

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: newsText,
      config: {
        systemInstruction: systemPrompt,
        responseMimeType: "application/json",
        temperature: 0.8, // Increased slightly for creativity in trick questions
      },
    });

    if (!response.text) {
      throw new Error("No response from AI");
    }

    const data = JSON.parse(response.text) as GeneratedQuestionBatch;

    // Basic validation
    if (!data.questions || !Array.isArray(data.questions) || data.questions.length === 0) {
        throw new Error("Invalid JSON structure: 'questions' array missing or empty.");
    }

    return data;
  } catch (error: any) {
    console.error("Failed to generate questions:", error);
    if (error.message?.includes('403') || error.status === 'PERMISSION_DENIED') {
        throw new Error("Akses ditolak (403). Pastikan API Key Anda valid dan memiliki izin untuk model ini.");
    }
    throw new Error("Gagal memproses soal dari AI. Silakan coba lagi.");
  }
};

export const processPdfToQuestions = async (base64Pdf: string, filename: string): Promise<GeneratedQuestionBatch> => {
  const ai = getAiInstance();
  const systemPrompt = getPdfSystemPrompt();

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME, 
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: "application/pdf",
              data: base64Pdf
            }
          },
          {
            text: `Analisis file PDF "${filename}". Prioritas: EKSTRAK soal-soal yang sudah ada di dalamnya menjadi JSON. Ambil sebanyak mungkin soal yang bisa dimuat. Jika tidak ada soal sama sekali, baru buatkan soal berdasarkan isinya.`
          }
        ]
      },
      config: {
        systemInstruction: systemPrompt,
        responseMimeType: "application/json",
        temperature: 0.2, // Low temperature for factual extraction
      },
    });

    if (!response.text) {
      throw new Error("No response from AI");
    }

    const data = JSON.parse(response.text) as GeneratedQuestionBatch;

    if (!data.questions || !Array.isArray(data.questions) || data.questions.length === 0) {
        throw new Error("Tidak ditemukan soal dalam PDF ini atau gagal memproses.");
    }

    return data;
  } catch (error: any) {
    console.error("Failed to parse JSON from PDF:", error);
    if (error.message?.includes('403') || error.status === 'PERMISSION_DENIED') {
        throw new Error("Akses ditolak (403). Pastikan API Key Anda valid.");
    }
    throw new Error("Gagal memproses PDF. Pastikan file dapat dibaca dan berisi teks/soal yang jelas.");
  }
};

export const getTrendingNews = async (): Promise<string> => {
  const ai = getAiInstance();

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: "Cari berita nasional Indonesia yang paling trending dan berdampak besar (High Impact) dalam 1 tahun terakhir. Prioritaskan topik: Pembangunan IKN, Kebijakan Ekonomi, Isu Politik/Hukum (Korupsi), atau Isu Sosial Strategis. Berita ini harus faktual dan cocok dijadikan studi kasus soal ujian CPNS (membutuhkan nalar). Berikan ringkasan 2-3 paragraf.",
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text || "Tidak dapat menemukan berita trending saat ini.";

    // Extract source URLs from grounding metadata
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const urls = chunks
      .map((chunk: any) => chunk.web?.uri)
      .filter((uri: string | undefined) => uri) as string[];

    // Remove duplicates
    const uniqueUrls = [...new Set(urls)];

    if (uniqueUrls.length > 0) {
      return `${text}\n\nSumber Referensi:\n${uniqueUrls.map(url => `- ${url}`).join('\n')}`;
    }

    return text;

  } catch (error: any) {
    console.warn("Google Search failed, falling back to internal knowledge:", error);

    // Fallback if Google Search is not allowed (403 Permission Denied)
    if (error.message?.includes('403') || error.status === 'PERMISSION_DENIED') {
        try {
             const fallbackResponse = await ai.models.generateContent({
                model: MODEL_NAME,
                contents: "Buat satu ringkasan berita simulasi (berdasarkan data nyata yang kamu ketahui 1 tahun terakhir) tentang isu nasional Indonesia (korupsi/bencana/kebijakan) yang cocok untuk soal CPNS. Tulis seolah-olah ini berita terkini. Berikan 2-3 paragraf.",
            });
            return (fallbackResponse.text || "") + "\n\n(Catatan: Berita ini digenerate dari pengetahuan internal AI karena akses Pencarian dibatasi)";
        } catch (fallbackError) {
             throw new Error("Gagal mengambil berita (Akses Ditolak).");
        }
    }

    throw new Error("Gagal mencari berita trending.");
  }
};

