const getAiInstance = () => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

/**
 * Helper to safely parse JSON from AI response
 * Removes markdown formatting and handles basic errors.
 */
const parseAiResponse = (text: string): GeneratedQuestionBatch => {
  // 1. Remove Markdown code blocks (```json ... ```)
  const cleaned = text.replace(/```json\s*/gi, '').replace(/```\s*$/, '').trim();

  try {
    const data = JSON.parse(cleaned);

    // Basic validation
    if (!data.questions || !Array.isArray(data.questions)) {
      throw new Error("Invalid structure: 'questions' array missing.");
    }

    return data as GeneratedQuestionBatch;
  } catch (error: any) {
    console.error("JSON Parse Fail. Raw text:", text);
    throw new Error(`Gagal membaca format data dari AI: ${error.message}. (Biasanya karena karakter ilegal dalam teks)`);
  }
};

export const generateQuestionBatch = async (newsText: string, categories: string[] = [], isHots: boolean = false): Promise<GeneratedQuestionBatch> => {
  const ai = getAiInstance();
  const systemPrompt = getSystemPrompt(categories, isHots);

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: newsText,
      config: {
        systemInstruction: systemPrompt,
        responseMimeType: "application/json",
        temperature: 0.8,
      },
    });

    if (!response.text) {
      throw new Error("No response from AI");
    }

    // Use safe parser
    const data = parseAiResponse(response.text);

    if (data.questions.length === 0) {
        throw new Error("AI tidak menghasilkan soal apapun.");
    }

    return data;
  } catch (error: any) {
    console.error("Failed to generate questions:", error);
    if (error.message?.includes('403') || error.status === 'PERMISSION_DENIED') {
        throw new Error("Akses ditolak (403). Pastikan API Key Anda valid dan memiliki izin untuk model ini.");
    }
    // Pass through the JSON error if it came from parseAiResponse
    throw error;
  }
};

