const getAiInstance = () => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

const parseAiResponse = (text: string): GeneratedQuestionBatch => {
  const cleaned = text.replace(/```json\s*/gi, '').replace(/```\s*$/, '').trim();
  try {
    const data = JSON.parse(cleaned);
    if (!data.questions || !Array.isArray(data.questions)) {
      throw new Error("Invalid structure.");
    }
    return data as GeneratedQuestionBatch;
  } catch (error: any) {
    console.error("JSON Parse Fail. Raw text:", text);
    throw new Error(`Gagal membaca format data dari AI: ${error.message}`);
  }
};

export const generateQuestionBatch = async (newsText: string, categories: string[] = [], isHots: boolean = false): Promise<GeneratedQuestionBatch> => {
  const ai = getAiInstance();
  const systemPrompt = getSystemPrompt(categories, isHots);
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: newsText,
      config: {
        systemInstruction: systemPrompt,
        responseMimeType: "application/json",
        temperature: 0.8,
      },
    });
    if (!response.text) throw new Error("No response from AI");
    return parseAiResponse(response.text);
  } catch (error: any) {
    if (error.message?.includes('403')) throw new Error("Akses ditolak (403). Cek API Key.");
    throw error;
  }
};

export const processPdfToQuestions = async (base64Pdf: string, filename: string): Promise<GeneratedQuestionBatch> => {
  const ai = getAiInstance();
  const systemPrompt = getPdfSystemPrompt();
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME, 
      contents: {
        parts: [
          { inlineData: { mimeType: "application/pdf", data: base64Pdf } },
          { text: `Proses PDF "${filename}". Ekstrak dan PERBAIKAN kualitas opsi jawaban agar lebih menantang dan homogen.` }
        ]
      },
      config: {
        systemInstruction: systemPrompt,
        responseMimeType: "application/json",
        temperature: 0.2, 
      },
    });
    if (!response.text) throw new Error("No response from AI");
    return parseAiResponse(response.text);
  } catch (error: any) {
    throw error;
  }
};

export const getTrendingNews = async (): Promise<string> => {
  const ai = getAiInstance();
  const today = new Date().toLocaleDateString('id-ID', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: `Konteks waktu: Hari ini adalah ${today}. Cari "Berita Terpopuler Indonesia Hari Ini" dari portal berita utama. Topik: Kebijakan Pemerintah, IKN, Isu Ekonomi Makro, Isu Sosial. Tulis ringkasan 2-3 paragraf.`,
      config: { tools: [{ googleSearch: {} }] },
    });
    const text = response.text;
    if (!text) throw new Error("Empty response");
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const urls = chunks.map((chunk: any) => chunk.web?.uri).filter(Boolean) as string[];
    const uniqueUrls = [...new Set(urls)];
    return uniqueUrls.length > 0 ? `${text}\n\nSumber Referensi:\n${uniqueUrls.map(url => `- ${url}`).join('\n')}` : text;
  } catch (error: any) {
    try {
        const fallbackResponse = await ai.models.generateContent({
            model: MODEL_NAME,
            contents: `Buat satu ringkasan berita simulasi isu nasional Indonesia (korupsi/bencana/kebijakan) tertanggal ${today}. 2-3 paragraf.`,
        });
        return (fallbackResponse.text || "") + "\n\n(Catatan: Berita simulasi AI)";
    } catch (fallbackError: any) {
        throw new Error(`Gagal mencari berita: ${error.message}`);
