const getAiInstance = () => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

const parseAiResponse = (text: string): GeneratedQuestionBatch => {
  const cleaned = text.replace(/```json\s*/gi, '').replace(/```\s*$/, '').trim();
  try {
    const data = JSON.parse(cleaned);
    if (!data.questions || !Array.isArray(data.questions)) {
      throw new Error("Invalid structure.");
    }
    return data as GeneratedQuestionBatch;
  } catch (error: any) {
    console.error("JSON Parse Fail. Raw text:", text);
    throw new Error(`Gagal membaca format data dari AI: ${error.message}`);
  }
};

export const generateQuestionBatch = async (newsText: string, categories: string[] = [], isHots: boolean = false): Promise<GeneratedQuestionBatch> => {
  const ai = getAiInstance();
  const systemPrompt = getSystemPrompt(categories, isHots);
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: newsText,
      config: {
        systemInstruction: systemPrompt,
        responseMimeType: "application/json",
        temperature: 0.8,
      },
    });
    if (!response.text) throw new Error("No response from AI");
    return parseAiResponse(response.text);
  } catch (error: any) {
    console.error("Generate Question Error:", error);
    if (error.message?.includes('403') || error.toString().includes('PERMISSION_DENIED')) {
        throw new Error("Akses model ditolak (403). Pastikan API Key Anda valid.");
    }
    throw error;
  }
};

