    const urls = chunks.map((chunk: any) => chunk.web?.uri).filter(Boolean) as string[];
    const uniqueUrls = [...new Set(urls)];

    return uniqueUrls.length > 0 
      ? `${text}\n\nSumber Referensi:\n${uniqueUrls.map(url => `- ${url}`).join('\n')}` 
