    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: `Konteks waktu: Hari ini adalah ${today}. Cari "Berita Terpopuler Indonesia Hari Ini" dari portal berita utama. Topik: Kebijakan Pemerintah, IKN, Isu Ekonomi Makro, Isu Sosial. Tulis ringkasan 2-3 paragraf.`,
      config: { tools: [{ googleSearch: {} }] },
    });
    const text = response.text;
    if (!text) throw new Error("Empty response");

    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const urls = chunks.map((chunk: any) => chunk.web?.uri).filter(Boolean) as string[];
    const uniqueUrls = [...new Set(urls)];

    return uniqueUrls.length > 0 
      ? `${text}\n\nSumber Referensi:\n${uniqueUrls.map(url => `- ${url}`).join('\n')}` 
      : text;

  } catch (searchError: any) {
    // 2. Fallback: AI Internal Knowledge (No Tools)
    try {
        // console.log("Attempting internal knowledge fallback...");
        const fallbackResponse = await ai.models.generateContent({
            model: MODEL_NAME,
            contents: `Buat satu ringkasan berita simulasi yang REALISTIS tentang isu nasional Indonesia (misal: IKN, Kebijakan Ekonomi, atau Infrastruktur) seolah-olah terjadi pada ${today}. Panjang 2-3 paragraf untuk bahan soal ujian CPNS.`,
        });

        const fallbackText = fallbackResponse.text;
        if (!fallbackText) throw new Error("Empty fallback response");
        return fallbackText + "\n\n(Catatan: Berita ini disimulasikan oleh AI karena akses pencarian sedang terbatas)";

    } catch (fallbackError: any) {
        // Changed to warn to avoid cluttering console with "Errors" when it's actually handled
        console.warn("Internal Knowledge Fallback Failed (Using Static Text):", fallbackError.message);

        // 3. Last Resort: Hardcoded Static Text (Guarantees App Functionality)
        return `SIMULASI BERITA DARURAT (Mode Offline):

Pemerintah Republik Indonesia hari ini mengumumkan percepatan transformasi digital nasional dengan target inklusi keuangan mencapai 90% pada akhir tahun 2025. Program ini melibatkan sinergi antara Bank Indonesia, Kementerian Kominfo, dan OJK untuk memperluas penggunaan QRIS di wilayah 3T (Tertinggal, Terdepan, dan Terluar). Kebijakan ini diharapkan dapat mendongkrak UMKM lokal agar mampu bersaing di pasar global.

(Berita ini adalah teks statis darurat karena AI sedang tidak dapat diakses. Gunakan teks ini untuk latihan soal).`;
    }
  }
};

