// AGENT 3: THE AUDITOR (Quality Control)
const OPENROUTER_API_KEY = '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';
const QC_MODEL = 'xiaomi/mimo-v2-flash:free';

export const auditAndRefineQuestions = async (draftJsonString: string): Promise<GeneratedQuestionBatch> => {

  const prompt = `
    Anda adalah **AUDITOR KUALITAS (QC)**. Tugas Anda memeriksa output JSON soal CPNS.

    INPUT JSON:
    ${draftJsonString}

    CHECKLIST KUALITAS:
    1. Pastikan JSON valid dan sesuai skema.
    2. Pastikan tidak ada kunci jawaban ganda (kecuali TKP).
    3. Pastikan penjelasan (explanation) masuk akal dan mendidik.
    4. Pastikan soal TKP memiliki poin 1-5 lengkap.
    5. Jika ada formatting markdown (seperti **bold**) di dalam string JSON, bersihkan jika merusak format.

    OUTPUT:
    Kembalikan JSON yang sudah divalidasi dan diperbaiki (jika perlu).
    JANGAN ubah konten soal secara drastis jika sudah bagus.
    HANYA return JSON murni.
  `;

  try {
    const response = await fetch("https://openrouter.ai/api/v1/chat/completions", {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${OPENROUTER_API_KEY}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        model: QC_MODEL,
        messages: [
          { role: "user", content: prompt }
        ],
        temperature: 0.2 // Low temperature for consistent validation
      })
    });

    if (!response.ok) {
         // If QC fails (e.g. rate limit), fallback to returning the draft
         console.warn("QC Agent unavailable, returning draft.");
         return JSON.parse(draftJsonString);
    }

    const data = await response.json();
    const content = data.choices[0]?.message?.content || draftJsonString;

    // Clean code blocks if model adds them
    const cleaned = content.replace(/```json\s*/gi, '').replace(/```\s*$/, '').trim();

    return JSON.parse(cleaned) as GeneratedQuestionBatch;

  } catch (error) {
    console.error("Quality Agent Error (Skipping QC):", error);
    // Fail safe: return the original draft if QC crashes
    try {
        return JSON.parse(draftJsonString);
    } catch (e) {
        throw new Error("Gagal parsing draft JSON (Critical Error).");
    }
  }
};

import { fetchNewsContext, extractPdfContext } from "./geminiAgent";
import { generateDraftQuestions } from "./mistralAgent";
import { auditAndRefineQuestions } from "./qualityAgent";
import { GeneratedQuestionBatch } from "../types";

export type ProcessStage = 'IDLE' | 'FETCHING_CONTEXT' | 'GENERATING_CONTENT' | 'QUALITY_CONTROL' | 'COMPLETED' | 'ERROR';

export const runAgentWorkflow = async (
  mode: 'NEWS' | 'PDF',
  input: string, // text search query OR base64 PDF
  categories: string[],
  isHots: boolean,
  onStatusUpdate?: (stage: ProcessStage) => void
): Promise<GeneratedQuestionBatch> => {

  try {
    // 1. AGENT A: SCOUT (Gemini)
    if (onStatusUpdate) onStatusUpdate('FETCHING_CONTEXT');
    let contextMaterial = "";

    if (mode === 'NEWS') {
      // If input is short (search query), we fetch news. If it's a long text pasted by user, we use it directly + fetch grounding.
      if (input.length > 200) {
         contextMaterial = input; // Use user pasted text directly
      } else {
         // Gemini searches based on input or gets trending if input empty
         // We reuse the fetchNewsContext but conceptually passing the input query would be better. 
         // For now, sticking to the existing pattern of trending news if no text provided.
         contextMaterial = await fetchNewsContext();
      }
    } else {
      // PDF Mode
      // input here is base64, second arg needs to be filename (passed via a struct or simplified)
      // We will assume input is base64 for now. Filename handling would require changing signature slightly, 
      // but let's assume 'Uploaded PDF' for generic name.
      contextMaterial = await extractPdfContext(input, "Uploaded Document");
    }

    // 2. AGENT B: ARCHITECT (Mistral)
    if (onStatusUpdate) onStatusUpdate('GENERATING_CONTENT');
    const draftJson = await generateDraftQuestions(contextMaterial, categories, isHots);

    // 3. AGENT C: AUDITOR (Xiaomi/Mimo)
    if (onStatusUpdate) onStatusUpdate('QUALITY_CONTROL');
    const finalBatch = await auditAndRefineQuestions(draftJson);

    if (onStatusUpdate) onStatusUpdate('COMPLETED');
    return finalBatch;

  } catch (error) {
    if (onStatusUpdate) onStatusUpdate('ERROR');
    throw error;
  }
};

