import { fetchNewsContext } from '../services/geminiAgent';

interface InputSectionProps {
  onGenerate: (text: string, categories: string[], isHots: boolean) => void;
  isLoading: boolean;
}

const InputSection: React.FC<InputSectionProps> = ({ onGenerate, isLoading }) => {
  const [text, setText] = useState('');
  const [isNewsLoading, setIsNewsLoading] = useState(false);
  const [selectedCategories, setSelectedCategories] = useState<string[]>(['TWK', 'TIU', 'TKP']);
  const [isHots, setIsHots] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (text.trim() && selectedCategories.length > 0) {
      onGenerate(text, selectedCategories, isHots);
    }
  };

  const handleCategoryChange = (category: string) => {
    setSelectedCategories(prev => {
      if (prev.includes(category)) {
        return prev.filter(c => c !== category);
      } else {
        return [...prev, category];
      }
    });
  };

  const handlePasteSample = () => {
    const sample = "Pemerintah berencana menerapkan sistem identitas digital terpadu untuk seluruh layanan publik mulai tahun depan. Langkah ini diharapkan dapat memangkas birokrasi, namun memicu kekhawatiran terkait keamanan data pribadi warga negara di tengah maraknya kasus kebocoran data.";
    setText(sample);
  };

  const handleFetchNews = async () => {
    setIsNewsLoading(true);
    try {
      const news = await fetchNewsContext();
      setText(news);
    } catch (error) {
      alert("Gagal mengambil berita trending. Silakan coba lagi.");
      console.error(error);
    } finally {
      setIsNewsLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-lg shadow-md p-6 max-w-2xl mx-auto border-t-4 border-blue-600">
      <h2 className="text-xl font-bold text-gray-800 mb-4">Input Berita / Topik</h2>
      <p className="text-sm text-gray-600 mb-4">
        Masukkan potongan berita, artikel, atau topik terkini untuk dijadikan bahan soal SKD.
      </p>

      <form onSubmit={handleSubmit} className="space-y-4">
        <textarea
          className="w-full h-40 p-3 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition resize-none font-sans text-gray-700"
          placeholder="Contoh: Pemerintah meresmikan bendungan baru di Jawa Barat untuk mengantisipasi banjir tahunan..."
          value={text}
          onChange={(e) => setText(e.target.value)}
          disabled={isLoading || isNewsLoading}
        ></textarea>

        {/* Configuration Row */}
        <div className="flex flex-col md:flex-row gap-4 items-start md:items-stretch">
            {/* Category Selection */}
            <div className="bg-gray-50 p-3 rounded-md border border-gray-200 flex-1 w-full">
                <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Pilih Kategori:</label>
                <div className="flex flex-wrap gap-x-4 gap-y-2">
                    {['TWK', 'TIU', 'TKP'].map((cat) => (
                    <label key={cat} className="flex items-center gap-2 cursor-pointer">
                        <input 
                        type="checkbox" 
                        checked={selectedCategories.includes(cat)}
                        onChange={() => handleCategoryChange(cat)}
                        className="w-4 h-4 text-blue-600 rounded focus:ring-blue-500"
                        disabled={isLoading}
                        />
                        <span className={`text-sm font-medium ${selectedCategories.includes(cat) ? 'text-gray-800' : 'text-gray-500'}`}>
                        {cat}
                        </span>
                    </label>
                    ))}
                </div>
            </div>

            {/* HOTS Toggle */}
            <div className="bg-gray-50 p-3 rounded-md border border-gray-200 w-full md:w-48 flex flex-col justify-center">
                 <label className="flex items-center gap-3 cursor-pointer">
                    <div className="relative">
                      <input 
                        type="checkbox" 
                        className="sr-only" 
                        checked={isHots} 
                        onChange={(e) => setIsHots(e.target.checked)}
                        disabled={isLoading}
                      />
                      <div className={`block w-10 h-6 rounded-full transition ${isHots ? 'bg-orange-500' : 'bg-gray-300'}`}></div>
                      <div className={`dot absolute left-1 top-1 bg-white w-4 h-4 rounded-full transition transform ${isHots ? 'translate-x-4' : 'translate-x-0'}`}></div>
                    </div>
                    <div className="text-sm font-bold text-gray-700">
                      Mode HOTS 🔥
                    </div>
                  </label>
                  <p className="text-xs text-gray-500 mt-1 pl-1">High Order Thinking Skills</p>
            </div>
        </div>

        {selectedCategories.length === 0 && (
            <p className="text-xs text-red-500 mt-0">Pilih minimal satu kategori.</p>
        )}

        <div className="flex flex-col sm:flex-row justify-between items-center gap-4 mt-6">
          <div className="flex gap-2 w-full sm:w-auto">
            <button
              type="button"
              onClick={handleFetchNews}
              className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-3 py-2 text-sm border border-blue-200 bg-blue-50 text-blue-700 rounded hover:bg-blue-100 transition disabled:opacity-50"
              disabled={isLoading || isNewsLoading}
            >
              {isNewsLoading ? (
                 <svg className="animate-spin h-4 w-4" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
              ) : (
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 20H5a2 2 0 01-2-2V6a2 2 0 012-2h10a2 2 0 012 2v1m2 13a2 2 0 01-2-2V7m2 13a2 2 0 002-2V9a2 2 0 00-2-2h-2m-4-3H9M7 16h6M7 8h6v4H7V8z"></path></svg>
              )}
              Cari Berita Trending
            </button>

            <button
              type="button"
              onClick={handlePasteSample}
              className="flex-1 sm:flex-none text-sm text-gray-500 hover:text-gray-700 font-medium disabled:opacity-50 underline decoration-dotted"
              disabled={isLoading || isNewsLoading}
            >
              Tempel Contoh
            </button>
          </div>

          <button
            type="submit"
            disabled={isLoading || isNewsLoading || !text.trim() || selectedCategories.length === 0}
            className={`w-full sm:w-auto px-6 py-2.5 rounded-md font-semibold text-white shadow-sm transition-all
              ${isLoading || isNewsLoading || !text.trim() || selectedCategories.length === 0
                ? 'bg-gray-400 cursor-not-allowed' 
                : 'bg-blue-600 hover:bg-blue-700 active:transform active:scale-95'
              }`}
          >
            {isLoading ? (
              <span className="flex items-center justify-center gap-2">
                <svg className="animate-spin h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                Memproses...
              </span>
            ) : (
              'Buat Soal'
            )}
          </button>
        </div>
      </form>
    </div>
  );
};

export default InputSection;

import { GoogleGenAI } from "@google/genai";

const MODEL_NAME = 'gemini-3-flash-preview'; 

const getAiInstance = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

// ROLE: NEWS FETCHER & TOPIC GENERATOR
// This agent does NOT generate questions. It generates the 'Source Material'.
export const fetchNewsContext = async (): Promise<string> => {
  const ai = getAiInstance();
  const today = new Date().toLocaleDateString('id-ID', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: `Cari berita terpopuler Indonesia hari ini (${today}). 
      Analisis 3 isu krusial (Ekonomi, Politik, Sosial) yang cocok untuk dijadikan bahan ujian CPNS (TWK/TIU/TKP).
      Berikan ringkasan padat dan mendalam untuk setiap topik, termasuk data faktual jika ada.
      Jangan buat soal, hanya materi sumber.`,
      config: { 
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text;
    // Note: text() method is not used, property .text is used, which is correct.
    if (!text) throw new Error("Empty response from Gemini Grounding");

    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const urls = chunks.map((chunk: any) => chunk.web?.uri).filter(Boolean) as string[];
    const uniqueUrls = [...new Set(urls)];

    return uniqueUrls.length > 0 
      ? `CONTEXT MATERIAL (Source: Gemini Grounding):\n${text}\n\nREFERENCES:\n${uniqueUrls.join('\n')}` 
      : text;

  } catch (error: any) {
    console.warn("Gemini Search failed, using simulation:", error);
    return `CONTEXT MATERIAL (Simulation Mode - ${today}):
    Isu 1: Transformasi Digital Birokrasi. Pemerintah mempercepat integrasi data nasional (Satu Data Indonesia) untuk efisiensi layanan publik.
    Isu 2: Ketahanan Pangan Nasional. Fokus pada diversifikasi pangan lokal mengurangi ketergantungan impor beras di tengah cuaca ekstrem.
    Isu 3: Etika Digital ASN. Peningkatan kasus pelanggaran netralitas ASN di media sosial menjelang tahun politik.`;
  }
};

// For PDF, Gemini extracts text and identifies key topics
export const extractPdfContext = async (base64Pdf: string, filename: string): Promise<string> => {
  const ai = getAiInstance();
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME, 
      contents: {
        parts: [
          { inlineData: { mimeType: "application/pdf", data: base64Pdf } },
          { text: `Analisis dokumen PDF "${filename}". Ekstrak teks utama dan identifikasi topik-topik kunci yang terkandung di dalamnya. Berikan ringkasan materi yang komprehensif untuk dijadikan bahan pembuatan soal.` }
        ]
      },
    });
    return response.text || "Gagal mengekstrak teks PDF.";
  } catch (error: any) {
    console.error("Gemini PDF Extraction Error:", error);
    throw new Error("Gemini gagal memproses PDF.");
  }
};

