const MISTRAL_API_KEY = '2RBeOKtifRnwhEPXnPVyGRBUIjoZxO8M';
const MISTRAL_ENDPOINT = 'https://api.mistral.ai/v1/chat/completions';

export const generateDraftQuestions = async (contextMaterial: string, categories: string[], isHots: boolean): Promise<string> => {

  const hotsInstruction = isHots 
    ? "LEVEL: HOTS (High Order Thinking Skills). Soal harus berbasis analisis kasus, penalaran mendalam, bukan hafalan. Opsi jawaban harus homogen dan mengecoh."
    : "LEVEL: Standar CAT CPNS. Kesulitan moderat.";

  const tkpGuidelines = `
  ## PANDUAN KHUSUS TKP (Tes Karakteristik Pribadi) - WAJIB DIPATUHI
  Soal TKP menilai **kecenderungan perilaku** dalam situasi kerja ASN, bukan benar/salah biner.
  Setiap soal harus memiliki 5 opsi dengan bobot nilai 1-5 (Skala Likert tersembunyi).

  1. **SKEMA SKOR OPSI (1-5):**
     - **Skor 5 (Terbaik):** Perilaku ASN ideal: seimbang, akuntabel, proaktif, menjaga kepercayaan publik & institusi.
     - **Skor 4:** Niat baik, tapi ada sedikit kelemahan (kurang inisiatif / dampak kurang luas).
     - **Skor 3:** Netral/pasif: main aman, menghindari konflik, tapi minim nilai tambah.
     - **Skor 2:** Bermasalah: egois, lari dari tanggung jawab, fokus jangka pendek.
     - **Skor 1 (Terburuk):** Melanggar etika, diskriminatif, radikal, atau ceroboh.

  2. **ANCHOR KOMPETENSI (Pilih satu dominan per soal):**
     - **Pelayanan Publik:** Responsif, adil, solusi tuntas. (Bukan sekadar "asal bapak senang").
     - **Jejaring Kerja:** Kolaborasi, sinergi, komunikasi persuasif.
     - **Sosial Budaya:** Toleransi, empati, adaptasi di lingkungan majemuk.
     - **TIK:** Penggunaan teknologi yang etis, efektif, dan hati-hati.
     - **Anti Radikalisme:** Kesetiaan pada Pancasila, tegas menolak kekerasan namun tetap tenang.
     - **Integritas:** Jujur, konsisten, berani menolak penyimpangan.

  3. **DESAIN STEM SOAL:**
     - Gunakan sudut pandang orang pertama ("Anda...") atau peran spesifik di tempat kerja.
     - Situasi harus **realistis**, mengandung dilema (misal: kecepatan vs aturan, empati vs SOP).
     - Hindari situasi yang terlalu hitam-putih (kriminal jelas) atau terlalu heroik.

  4. **OUTPUT PENJELASAN:**
     - Jelaskan kenapa opsi skor 5 paling tepat dibanding skor 4.
     - Hubungkan dengan nilai/kompetensi yang diuji.
  `;

  const prompt = `
    Anda adalah **MISTRAL ARCHITECT**, mesin pembuat soal CPNS kelas dunia.

    SUMBER MATERI:
    ${contextMaterial}

    TUGAS:
    Buat 3 soal latihan (Format JSON) berdasarkan materi di atas.
    Kategori wajib: ${categories.join(', ') || 'TWK, TIU, TKP'}.
    ${hotsInstruction}

    ${categories.includes('TKP') || categories.length === 0 ? tkpGuidelines : ''}

    ATURAN STRUKTUR JSON (WAJIB DIPATUHI):
    {
      "questions": [
        {
          "meta": { "news_topic": "Judul Topik", "question_type": "Standard/HOTS" },
          "content": {
            "category": "TWK/TIU/TKP",
            "topic": "Topik Utama",
            "subtopic": "Subtopik (Misal: Pelayanan Publik)",
            "question_text": "Narasi soal dan pertanyaan...",
            "options": { "A": "...", "B": "...", "C": "...", "D": "...", "E": "..." },
            "answer_key": {
              "correct_option": "A", 
              "tkp_points": { "A": 1, "B": 2, "C": 3, "D": 4, "E": 5 } (WAJIB ADA untuk TKP, null untuk TWK/TIU)
            },
            "explanation": "Penjelasan lengkap..."
          }
        }
      ]
    }

    Hanya output JSON valid. Jangan ada teks pembuka/penutup.
  `;

  try {
    const response = await fetch(MISTRAL_ENDPOINT, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${MISTRAL_API_KEY}`
      },
      body: JSON.stringify({
        model: "mistral-large-latest",
        messages: [{ role: "user", content: prompt }],
        temperature: 0.7,
        response_format: { type: "json_object" }
      })
    });

    if (!response.ok) {
        const err = await response.text();
        throw new Error(`Mistral API Error: ${err}`);
    }

    const data = await response.json();
    return data.choices[0].message.content;

  } catch (error) {
    console.error("Mistral Agent Error:", error);
    throw error;
  }
};

