import { GeneratedQuestionBatch } from "../types";

// AGENT 2: THE ARCHITECT (Generates Questions)
const MISTRAL_API_KEY = '2RBeOKtifRnwhEPXnPVyGRBUIjoZxO8M';
const MISTRAL_ENDPOINT = 'https://api.mistral.ai/v1/chat/completions';

// Helper to make the actual API call
const callMistral = async (prompt: string): Promise<any> => {
  try {
    const response = await fetch(MISTRAL_ENDPOINT, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${MISTRAL_API_KEY}`
      },
      body: JSON.stringify({
        model: "mistral-large-latest",
        messages: [{ role: "user", content: prompt }],
        temperature: 0.7, 
        response_format: { type: "json_object" }
      })
    });

    if (!response.ok) {
        const err = await response.text();
        throw new Error(`Mistral API Error: ${err}`);
    }

    const data = await response.json();
    const content = data.choices[0].message.content;
    return JSON.parse(content);

  } catch (error) {
    console.error("Mistral Call Error:", error);
    // Return structure that won't break array spreading
    return { questions: [] }; 
  }
};

const generateTwkQuestions = async (context: string, count: number, isHots: boolean) => {
  if (count <= 0) return [];

  const hotsInstruction = isHots 
    ? "LEVEL: HOTS. Buat soal yang meminta analisis kaitan peristiwa dengan sila Pancasila, UUD 1945, atau integritas nasional. Hindari pertanyaan hafalan tahun/tanggal."
    : "LEVEL: Standar CAT CPNS. Fokus pada wawasan kebangsaan.";

  const prompt = `
    Anda adalah **AGENT A: SPECIALIST TWK (Tes Wawasan Kebangsaan)**.

    KONTEKS BERITA:
    ${context}

    TUGAS:
    Buat ${count} soal TWK berdasarkan topik berita di atas.
    Fokus: Nasionalisme, Integritas, Bela Negara, Pilar Negara (Pancasila, UUD 45, NKRI, Bhinneka Tunggal Ika).

    ${hotsInstruction}

    FORMAT JSON (Array of objects):
    {
      "questions": [
        {
          "meta": { "news_topic": "Topik Berita", "question_type": "TWK" },
          "content": {
            "category": "TWK",
            "topic": "Pilar Negara / Nasionalisme / dll",
            "subtopic": "Subtopik spesifik",
            "question_text": "...",
            "options": { "A": "...", "B": "...", "C": "...", "D": "...", "E": "..." },
            "answer_key": {
              "correct_option": "A", 
              "tkp_points": null
            },
            "explanation": "Jelaskan kenapa jawaban tersebut benar berdasarkan landasan hukum atau teori kebangsaan."
          }
        }
      ]
    }
  `;
  const result = await callMistral(prompt);
  return result.questions || [];
};

const generateTiuQuestions = async (context: string, count: number, isHots: boolean) => {
  if (count <= 0) return [];

  const prompt = `
    Anda adalah **AGENT B: SPECIALIST TIU (Tes Intelegensia Umum)**.

    KONTEKS BERITA:
    ${context}

    TUGAS:
    Buat ${count} soal TIU. Gunakan informasi atau istilah dari berita sebagai bahan soal jika memungkinkan, namun fokus utamanya adalah LOGIKA dan HITUNGAN.

    VARIASI SOAL (Harus berbeda-beda):
    1. **Silogisme/Logika:** Buat premis dari fakta berita (misal: "Semua koruptor dihukum", "Pejabat X koruptor"), minta kesimpulan.
    2. **Soal Cerita Numerik:** Ambil angka/data dari berita untuk soal hitungan (persentase, perbandingan, kecepatan, dll). Jika tidak ada angka, buat skenario fiktif yang relevan dengan topik.
    3. **Analogi Verbal:** Hubungan kata yang relevan dengan topik berita.

    SYARAT:
    - Harus ada SATU jawaban benar yang mutlak (logis/matematis).
    - Jangan buat soal opini.

    FORMAT JSON:
    {
      "questions": [
        {
          "meta": { "news_topic": "Topik Berita", "question_type": "TIU" },
          "content": {
            "category": "TIU",
            "topic": "Logika / Numerik / Verbal",
            "subtopic": "Silogisme / Aritmatika",
            "question_text": "...",
            "options": { "A": "...", "B": "...", "C": "...", "D": "...", "E": "..." },
            "answer_key": {
              "correct_option": "A", 
              "tkp_points": null
            },
            "explanation": "Jelaskan langkah penyelesaian logika atau rumus matematikanya."
          }
        }
      ]
    }
  `;
  const result = await callMistral(prompt);
  return result.questions || [];
};

const generateTkpQuestions = async (context: string, count: number) => {
  if (count <= 0) return [];

  const prompt = `
    Anda adalah **AGENT C: SPECIALIST TKP (Tes Karakteristik Pribadi)**.

    KONTEKS BERITA:
    ${context}

    TUGAS:
    Buat ${count} soal TKP. 
    Ubah konteks berita menjadi **Skenario Situasi Kerja** bagi seorang ASN.
    (Misal berita tentang korupsi -> Buat soal tentang Integritas saat ditawari suap).

    ASPEK: Pelayanan Publik, Jejaring Kerja, Sosial Budaya, TIK, Profesionalisme, Anti Radikalisme.

    SYARAT MUTLAK:
    1. **Tidak ada jawaban Benar/Salah**.
    2. **Semua opsi (A-E) memiliki bobot nilai 1-5**.
    3. Skor 5 = Perilaku ASN paling ideal (Solutif, Tegas, Proaktif).
    4. Skor 1 = Perilaku terburuk (Pasif, Emosional, Melanggar aturan).
    5. Opsi harus berupa tindakan konkrit.

    FORMAT JSON:
    {
      "questions": [
        {
          "meta": { "news_topic": "Topik Berita", "question_type": "TKP" },
          "content": {
            "category": "TKP",
            "topic": "Pelayanan Publik / dll",
            "subtopic": "Integritas / Kerjasama",
            "question_text": "Anda adalah pegawai di instansi X. Situasi: [Situasi dari berita]. Bagaimana sikap Anda?",
            "options": { "A": "...", "B": "...", "C": "...", "D": "...", "E": "..." },
            "answer_key": {
              "correct_option": "E", 
              "tkp_points": { "A": 1, "B": 2, "C": 3, "D": 4, "E": 5 } 
            },
            "explanation": "Urutan prioritas: E (5) karena..., D (4) karena..."
          }
        }
      ]
    }

    PENTING: Pastikan kunci "tkp_points" terisi lengkap dan masuk akal.
  `;
  const result = await callMistral(prompt);
  return result.questions || [];
};


// MAIN DISPATCHER
export const generateDraftQuestions = async (contextMaterial: string, categories: string[], isHots: boolean): Promise<string> => {
  const totalQuestions = 6;
  const cats = categories.length > 0 ? categories : ['TWK', 'TIU', 'TKP'];

  // Calculate quotas
  const countPerCat = Math.floor(totalQuestions / cats.length);
  const remainder = totalQuestions % cats.length;

  // Helper to distribute remainder
  // e.g., 6 questions, 3 cats -> 2, 2, 2
  // e.g., 6 questions, 2 cats -> 3, 3
  // e.g., 6 questions, 4 cats (impossible here but logic holds) -> 2, 2, 1, 1 (simplified)
  let currentRemainder = remainder;

  const getCount = () => {
      let c = countPerCat;
      if (currentRemainder > 0) {
          c++;
          currentRemainder--;
      }
      return c;
  };

  const promises: Promise<any>[] = [];

  // Dispatch to specialized agents
  if (cats.includes('TWK')) {
    promises.push(generateTwkQuestions(contextMaterial, getCount(), isHots));
  }
  if (cats.includes('TIU')) {
    promises.push(generateTiuQuestions(contextMaterial, getCount(), isHots));
  }
  if (cats.includes('TKP')) {
    promises.push(generateTkpQuestions(contextMaterial, getCount()));
  }

  try {
    const results = await Promise.all(promises);
    const flattenedQuestions = results.flat();

    if (flattenedQuestions.length === 0) {
        throw new Error("Gagal membuat soal. Mohon coba lagi.");
    }

    // Shuffle results so categories are mixed
    const shuffled = flattenedQuestions.sort(() => Math.random() - 0.5);

    return JSON.stringify({ questions: shuffled });

  } catch (error) {
     console.error("Orchestration Error:", error);
     throw error;
  }
};

import React, { useState } from 'react';

interface InputSectionProps {
  onGenerate: (text: string, categories: string[], isHots: boolean) => void;
  isLoading: boolean;
}

const InputSection: React.FC<InputSectionProps> = ({ onGenerate, isLoading }) => {
  const [text, setText] = useState('');
  // Single selection state, default to TWK
  const [selectedCategory, setSelectedCategory] = useState<string>('TWK');
  const [isHots, setIsHots] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // Pass as array to maintain compatibility with Orchestrator
    onGenerate(text, [selectedCategory], isHots);
  };

  const getButtonText = () => {
    if (isLoading) return 'Memproses...';
    if (!text.trim()) return `Cari Berita & Buat Soal ${selectedCategory}`;
    if (text.length < 200) return `Topik "${text.substring(0, 10)}..." -> Soal ${selectedCategory}`;
    return `Analisis Teks -> Soal ${selectedCategory}`;
  };

  return (
    <div className="bg-white rounded-lg shadow-md p-6 max-w-2xl mx-auto border-t-4 border-blue-600">
      <h2 className="text-xl font-bold text-gray-800 mb-4">Input Berita / Topik</h2>
      <p className="text-sm text-gray-600 mb-4">
        Masukkan topik spesifik (misal: "IKN", "Pemilu") atau teks berita lengkap. <br/>
        <span className="font-semibold text-blue-600">Biarkan kosong</span> untuk mencari berita trending hari ini secara otomatis.
      </p>

      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="relative">
          <textarea
            className="w-full h-32 p-3 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition resize-none font-sans text-gray-700"
            placeholder="Ketik topik (contoh: 'Hilirisasi Nikel') atau biarkan kosong untuk berita trending otomatis..."
            value={text}
            onChange={(e) => setText(e.target.value)}
            disabled={isLoading}
          ></textarea>
          {/* Helper for empty state */}
          {!text.trim() && !isLoading && (
            <div className="absolute bottom-3 right-3 text-xs text-gray-400 italic pointer-events-none">
              Mode Otomatis: Berita Trending
            </div>
          )}
        </div>

        {/* Configuration Row */}
        <div className="flex flex-col md:flex-row gap-4 items-start md:items-stretch">
            {/* Category Selection (Single Select) */}
            <div className="bg-gray-50 p-3 rounded-md border border-gray-200 flex-1 w-full">
                <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Pilih Kategori (Fokus):</label>
                <div className="flex flex-wrap gap-x-4 gap-y-2">
                    {['TWK', 'TIU', 'TKP'].map((cat) => (
                    <label key={cat} className={`flex items-center gap-2 cursor-pointer p-2 rounded border transition-colors ${selectedCategory === cat ? 'bg-white border-blue-400 shadow-sm' : 'border-transparent hover:bg-gray-200'}`}>
                        <input 
                        type="radio" 
                        name="category_selection"
                        checked={selectedCategory === cat}
                        onChange={() => setSelectedCategory(cat)}
                        className="w-4 h-4 text-blue-600 focus:ring-blue-500"
                        disabled={isLoading}
                        />
                        <span className={`text-sm font-medium ${selectedCategory === cat ? 'text-blue-700 font-bold' : 'text-gray-500'}`}>
                        {cat}
                        </span>
                    </label>
                    ))}
                </div>
            </div>

            {/* HOTS Toggle */}
            <div className="bg-gray-50 p-3 rounded-md border border-gray-200 w-full md:w-48 flex flex-col justify-center">
                 <label className="flex items-center gap-3 cursor-pointer">
                    <div className="relative">
                      <input 
                        type="checkbox" 
                        className="sr-only" 
                        checked={isHots} 
                        onChange={(e) => setIsHots(e.target.checked)}
                        disabled={isLoading}
                      />
                      <div className={`w-10 h-6 rounded-full shadow-inner transition ${isHots ? 'bg-blue-600' : 'bg-gray-300'}`}></div>
                      <div className={`absolute top-1 left-1 w-4 h-4 bg-white rounded-full shadow transition transform ${isHots ? 'translate-x-4' : 'translate-x-0'}`}></div>
                    </div>
                    <span className="text-sm font-medium text-gray-700">Mode HOTS</span>
                 </label>
                 <p className="text-[10px] text-gray-500 mt-1 leading-tight">
                    Soal lebih analitis & kompleks (High Order Thinking).
                 </p>
            </div>
        </div>

        <button
          type="submit"
          disabled={isLoading}
          className={`w-full py-3 px-6 rounded-md text-white font-bold text-lg shadow-md transition-all transform active:scale-95
            ${isLoading 
              ? 'bg-gray-400 cursor-not-allowed' 
              : 'bg-gradient-to-r from-blue-600 to-blue-700 hover:from-blue-700 hover:to-blue-800 hover:shadow-lg'
            }`}
        >
          {getButtonText()}
        </button>
      </form>
    </div>
  );
};

export default InputSection;

import { GeneratedQuestionBatch } from "../types";

// AGENT 3: THE AUDITOR (Quality Control)
const OPENROUTER_API_KEY = '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';
const QC_MODEL = 'xiaomi/mimo-v2-flash:free';

export const auditAndRefineQuestions = async (draftJsonString: string): Promise<GeneratedQuestionBatch> => {

  const prompt = `
    Anda adalah **AUDITOR KUALITAS (QC)**. Tugas Anda memeriksa output JSON soal CPNS.

    INPUT JSON:
    ${draftJsonString}

    CHECKLIST KUALITAS & REVISI:
    1. **VALIDASI STRUKTUR**: Pastikan JSON valid, tidak ada kunci jawaban ganda (kecuali TKP).
    2. **MAKE IT TRICKY (PENGECOH)**: 
       - Periksa opsi jawaban yang salah (Distractor).
       - Ubah distractor yang terlalu mudah ditebak menjadi lebih logis dan mirip dengan jawaban benar.
       - Hindari opsi "Semua benar" atau "Tidak ada yang benar" kecuali sangat diperlukan.
    3. **MAKE IT CONCISE (PADAT)**:
       - Hapus kata-kata basa-basi ("Adapun", "Maka dari itu", "Sebagai berikut") yang tidak perlu.
       - Pastikan soal langsung pada inti masalah (To the point).
    4. **TKP SCORING**: Pastikan soal TKP memiliki poin 1-5 lengkap.
    5. **ACAK OPSI (SHUFFLE)**: 
       - Acak ulang posisi teks jawaban (Options A-E). 
       - Update 'answer_key.correct_option' dan 'tkp_points' sesuai posisi baru.

    OUTPUT:
    Kembalikan JSON yang sudah divalidasi, dipersulit (tricky), dipadatkan (concise), dan diacak.
    HANYA return JSON murni.
  `;

  try {
    const response = await fetch("https://openrouter.ai/api/v1/chat/completions", {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${OPENROUTER_API_KEY}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        model: QC_MODEL,
        messages: [
          { role: "user", content: prompt }
        ],
        temperature: 0.4 // Slightly increased for shuffling variability
      })
    });

    if (!response.ok) {
         // If QC fails (e.g. rate limit), fallback to returning the draft
         console.warn("QC Agent unavailable, returning draft.");
         return JSON.parse(draftJsonString);
    }

    const data = await response.json();
    const content = data.choices[0]?.message?.content || draftJsonString;

    // Clean code blocks if model adds them
    const cleaned = content.replace(/```json\s*/gi, '').replace(/```\s*$/, '').trim();

    return JSON.parse(cleaned) as GeneratedQuestionBatch;

  } catch (error) {
    console.error("Quality Agent Error (Skipping QC):", error);
    // Fail safe: return the original draft if QC crashes
    try {
        return JSON.parse(draftJsonString);
    } catch (e) {
        throw new Error("Gagal parsing draft JSON (Critical Error).");
    }
  }
};
